-- FILE: 20261021120000_char.sql
-- Necromancer talent trees T1: strip the 12 non-proficiency
-- trainer-learned talent shortcuts from existing class-10 characters.
-- Grim Reaper/Necro Knight/Will of the Death Knight stay on existing
-- characters (they carry proficiency skills/gear); new characters get
-- them from the Blood tree.  Generated by
-- tools/generate_talent_trees.py; re-runnable.

DELETE cs FROM `character_spell` cs
JOIN `characters` c ON c.guid = cs.guid
WHERE c.class = 10 AND cs.spell IN (61022, 61023, 61026, 61028, 61033, 61039, 61049, 61050, 61087, 61088, 61093, 61094);

DELETE cs FROM `character_spell_dual_spec` cs
JOIN `characters` c ON c.guid = cs.guid
WHERE c.class = 10 AND cs.spell IN (61022, 61023, 61026, 61028, 61033, 61039, 61049, 61050, 61087, 61088, 61093, 61094);

DELETE ca FROM `character_action` ca
JOIN `characters` c ON c.guid = ca.guid
WHERE c.class = 10 AND ca.type = 0 AND ca.action IN (61022, 61023, 61026, 61028, 61033, 61039, 61049, 61050, 61087, 61088, 61093, 61094);
